import React from 'react';
import { useTrail, animated, config } from 'react-spring';

const Skills = () => {
  const skills = [
    { category: 'Programming Languages', items: ['Java', 'Python', 'C', 'C++', 'SQL', 'JavaScript', 'C#', 'Julia'] },
    { category: 'Web Technologies', items: ['React', 'Node.js', 'HTML', 'CSS'] },
    { category: 'Tools & Platforms', items: ['Git', 'Figma', 'Canva', 'Jenkins', 'AWS', 'Unity', 'Android Studio', 'SPSS', 'R', 'R commander'] },
    { category: 'Databases', items: ['MySQL', 'MongoDB', 'SQLite'] }
  ];

  const trail = useTrail(skills.length, {
    from: { opacity: 0, transform: 'translateY(20px)' },
    to: { opacity: 1, transform: 'translateY(0)' },
    config: config.gentle,
  });

  return (
    <div className="skills-section">
      <h2>Skills</h2>
      {trail.map((props, index) => (
        <animated.div
          key={skills[index].category}
          style={props}
          className="skill-group"
        >
          <h3>{skills[index].category}</h3>
          <ul>
            {skills[index].items.map((skill) => (
              <li key={skill}>{skill}</li>
            ))}
          </ul>
        </animated.div>
      ))}
    </div>
  );
};

export default Skills;